//! Shared bin-prelude helpers used by `goal1` / `goal2` / `goalzc`.
//!
//! Collects the small formatting and parsing routines that
//! every binary in this crate duplicated before this module
//! existed:
//!
//! - [`parse_non_negative_secs`] — clap `value_parser` for
//!   non-negative finite `f64` durations.
//! - [`parse_pin_cores`] — turn the `--pin` CLI string into
//!   `Vec<usize>`; prints an error and exits `2` on bad input
//!   so every bin gets the same failure surface.
//! - [`print_banner`] — `"actor-x1 <version>"` one-liner;
//!   resolved from this crate's `CARGO_PKG_*` (bins share the
//!   package).
//! - [`print_apparatus`] — the `apparatus: framing=... ;
//!   loop_per_iter=... ; per-event at inner=N = ...` line.
//! - [`print_pinning`] — `pinning: none (unpinned)` or a
//!   comma-separated `actor<i>→core<n>` list.
//!
//! `--ticks` / `--decimals` flags and the per-actor
//! `probe.report(...)` call stay in each bin — those are
//! per-bin policy, not shared output.

use tprobe::pin;
use tprobe::{Overhead, fmt_commas, ticks};

/// Clap `value_parser` for non-negative finite `f64` durations
/// (seconds). Rejects negative, NaN, and infinite values with a
/// message Clap will surface on the offending flag.
pub fn parse_non_negative_secs(s: &str) -> Result<f64, String> {
    let v: f64 = s
        .parse()
        .map_err(|e: std::num::ParseFloatError| e.to_string())?;
    if !v.is_finite() || v < 0.0 {
        Err(format!("'{s}' is not a non-negative finite number"))
    } else {
        Ok(v)
    }
}

/// Parse the `--pin` CLI string into a list of logical-CPU
/// ids. `None` / empty input yields the empty list (unpinned).
///
/// On parse error, prints `error: --pin: <msg>` to stderr and
/// exits the process with code `2`. Centralizing the exit here
/// keeps the three bins free of duplicated error handling; no
/// caller wants to recover from a bad `--pin` value.
pub fn parse_pin_cores(spec: Option<&str>) -> Vec<usize> {
    match spec {
        None => vec![],
        Some(spec) => match pin::parse_cores(spec) {
            Ok(cores) => cores,
            Err(e) => {
                eprintln!("error: --pin: {e}");
                std::process::exit(2);
            }
        },
    }
}

/// Print the `"<pkg-name> <version>"` banner. Bins live in
/// the same crate as this module, so `env!` resolves to the
/// shared `actor-x1` values at compile time.
pub fn print_banner() {
    println!("{} {}", env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION"));
}

/// Print the `apparatus:` line: framing / loop-per-iter /
/// per-event overhead in ticks and nanoseconds.
///
/// - `inner` is the per-scope batch size used by the caller;
///   `per_event_ticks(inner)` reports the effective per-event
///   apparatus cost after the framing portion is amortized.
/// - `inner=1` is the unbatched case (goal2 / goalzc-probed).
pub fn print_apparatus(o: &Overhead, inner: u64) {
    let tpn = ticks::ticks_per_ns();
    let framing_ns = o.framing_ticks as f64 / tpn;
    let lpi_ns = o.loop_per_iter_ticks / tpn;
    let per_event_tk = o.per_event_ticks(inner);
    let per_event_ns = per_event_tk as f64 / tpn;
    println!(
        "  apparatus: framing={} tk ({:.2} ns); loop_per_iter={:.2} tk ({:.2} ns); per-event at inner={} = {} tk ({:.2} ns)",
        o.framing_ticks,
        framing_ns,
        o.loop_per_iter_ticks,
        lpi_ns,
        fmt_commas(inner),
        per_event_tk,
        per_event_ns,
    );
}

/// Print the `pinning:` line.
///
/// - Empty `pin_cores` → `pinning: none (unpinned)`.
/// - Otherwise → `pinning: actor0→core<c0>, actor1→core<c1>, ...`
///   with `actor<i>` pinned to `pin_cores[i % pin_cores.len()]`
///   (matches the wrap-around used by the runtimes).
pub fn print_pinning(pin_cores: &[usize], n_actors: usize) {
    if pin_cores.is_empty() {
        println!("  pinning: none (unpinned)");
    } else {
        let plan: Vec<String> = (0..n_actors)
            .map(|i| format!("actor{i}→core{}", pin_cores[i % pin_cores.len()]))
            .collect();
        println!("  pinning: {}", plan.join(", "));
    }
}

