41	    /// Measurement window in seconds (runs after warmup).
42	    #[arg(value_parser = report::parse_non_negative_secs)]
43	    duration_s: f64,
44	
45	    /// Warmup duration in seconds before measurement. Runs the
46	    /// same dispatch loop as the measurement phase (probe active)
47	    /// so cache/branch-predictor/frequency land in the same state
48	    /// by the time the probe is cleared and measurement begins.
