78	/// Parse CLI, run warmup + measurement on two single-thread
79	/// ping-pong actors, print message count + throughput, then
80	/// render the per-dispatch band-table report.
81	fn main() {
82	    let cli = Cli::parse();
83	
84	    report::print_banner();
85	
86	    // Pin the main thread before any work — calibration and the
87	    // dispatch loop both run here, so they share the pinned core.
