98	    rt.run_for(Duration::from_secs_f64(cli.warmup), cli.inner);
99	    rt.probe_mut().clear();
100	
101	    // Calibration runs on the warmed system, before measurement
102	    // begins, so freq/cache state matches what the probe will see
103	    // during measurement.
104	    let overhead = perf::calibrate();
105	
106	    // Measurement.
107	    let count = rt.run_for(Duration::from_secs_f64(cli.duration_s), cli.inner);
108	    let mmps = count as f64 / cli.duration_s / 1e6;
