113	        fmt_commas(cli.inner),
114	    );
115	    report::print_pinning_main(pin_core);
116	    report::print_apparatus(&overhead, cli.inner);
117	    println!();
118	    rt.probe_mut()
119	        .report(cli.ticks, Some(&overhead), cli.decimals);
