1	//! Goalzc binary: two zerocopy actors, each on its own thread,
2	//! ping-ponging a pool-backed `PooledMsg` (handler view: `&[u8]`)
3	//! over `std::sync::mpsc` channels for a caller-supplied
4	//! duration in seconds, after an optional warmup window.
5	//! Smoke generator for the pool-backed payload path: prints
6	//! messages-handled / aggregate throughput plus the `pinning:`
7	//! line if `--pin` was set.
8	//!
9	//! No diagnostic instrumentation in this version. Probing
10	//! re-enters post-`0.6.0` via an actor-wrapper trait or
11	//! `TProbe::Counter` (out of scope here).
12	//!
13	//! Compared to goal2 (unit `Message`), goalzc exercises the
14	//! `Pool` + `PooledMsg` path: every dispatch costs one `pool.get`
15	//! plus one drop-back. `--size N` sweeps payload size; pool is
16	//! sized for ping-pong steady state (2 buffers in flight) with
17	//! headroom (4 buffers) so a wakeup race never starves.
18	//!
19	//! Usage: `goalzc --help`
20	
21	use std::time::Duration;
22	
23	use actor_x1::actor_manager::{ActorManager, ActorZC, ContextZC};
24	use actor_x1::pool::{BufRefStore, Pool};
25	use actor_x1::runtime_zc::RuntimeZC;
26	use clap::Parser;
27	use tprobe::{fmt_commas, pin};
28	
29	/// Zerocopy ping-pong actor: on every inbound message, fabricate
30	/// a reply of the same length from the pool and forward it to
31	/// the configured peer. Drops the inbound `PooledMsg` after the
32	/// handler returns (runtime-owned), which returns its buffer to
33	/// the pool — so per dispatch we see exactly one pool `get` +
34	/// one pool `put`.
35	struct PingPongZC {
36	    peer_id: u32,
37	}
38	
39	impl<S: BufRefStore> ActorZC<S> for PingPongZC {
40	    /// Reply with a same-sized buffer to `self.peer_id`. Never blocks.
41	    fn handle_message(&mut self, ctx: &mut dyn ContextZC<S>, msg: &[u8]) {
42	        let reply = ctx.get_msg(msg.len()).expect("get_msg should succeed"); // OK: pool sized for ping-pong steady state (2 in flight; 4 capacity)
43	        ctx.send(self.peer_id, reply);
44	    }
45	}
46	
47	/// CLI for goalzc: two-thread two-actor zerocopy ping-pong
48	/// smoke generator. Reports aggregate throughput.
49	#[derive(Parser, Debug)]
50	#[command(
51	    version,
52	    about,
53	    long_about = None,
54	    max_term_width = 80,
55	    before_help = concat!(env!("CARGO_PKG_NAME"), " ", env!("CARGO_PKG_VERSION")),
56	)]
57	struct Cli {
58	    /// Measurement window in seconds (runs after warmup).
59	    #[arg(value_parser = parse_non_negative_secs)]
60	    duration_s: f64,
61	
62	    /// Warmup duration in seconds before measurement. Runs
63	    /// the same dispatch loop; per-thread counts are zeroed
64	    /// at the warmup → measurement boundary via
65	    /// `Handle::reset_count` so reported throughput reflects
66	    /// only the measurement window.
67	    #[arg(short = 'w', long, default_value_t = 0.5, value_parser = parse_non_negative_secs)]
68	    warmup: f64,
69	
70	    /// Message payload size in bytes. Pool is built with this
71	    /// `msg_size`, so `get_msg(size)` calls inside the handler
72	    /// always pass the bound check by construction. Must be
73	    /// `>= 1`.
74	    #[arg(short = 's', long, default_value_t = 64, value_parser = parse_positive_size)]
75	    size: u32,
76	
77	    /// Pin each actor thread to a logical CPU. Accepts a
78	    /// comma-separated / range list; actor `i` pins to
79	    /// `pin[i % pin.len()]`. Examples: `--pin 0,1` pairs two
80	    /// actors to two CPUs; `--pin 0` oversubscribes both onto
81	    /// one core. Tightens stdev by eliminating OS thread
82	    /// migration noise.
83	    #[arg(short = 'p', long)]
84	    pin: Option<String>,
85	}
86	
87	/// `value_parser` helper: reject negative, NaN, and infinite values.
88	fn parse_non_negative_secs(s: &str) -> Result<f64, String> {
89	    let v: f64 = s
90	        .parse()
91	        .map_err(|e: std::num::ParseFloatError| e.to_string())?;
92	    if !v.is_finite() || v < 0.0 {
93	        Err(format!("'{s}' is not a non-negative finite number"))
94	    } else {
95	        Ok(v)
96	    }
97	}
98	
99	/// `value_parser` helper: parse a positive (>=1) `u32`.
100	fn parse_positive_size(s: &str) -> Result<u32, String> {
101	    let v: u32 = s
102	        .parse()
103	        .map_err(|e: std::num::ParseIntError| e.to_string())?;
104	    if v == 0 {
105	        Err(format!("'{s}' must be >= 1"))
106	    } else {
107	        Ok(v)
108	    }
109	}
110	
111	/// Parse CLI, run two zerocopy ping-pong actors on their own
112	/// threads via the lifecycle API, print aggregate throughput.
113	fn main() {
114	    let cli = Cli::parse();
115	    println!("{} {}", env!("CARGO_PKG_NAME"), env!("CARGO_PKG_VERSION"),);
116	
117	    // Pool sized for ping-pong steady state (2 in flight) with
118	    // headroom; `Pool::new(size, 4)` makes the `--size` runtime
119	    // bound auto-satisfied since `pool.msg_size() == size`.
120	    let pool: Pool = Pool::new(cli.size, 4);
121	    let mut rt = RuntimeZC::new(pool.clone());
122	    let mut mgr = ActorManager::new("goalzc.dispatch");
123	    let a_id = mgr.add(PingPongZC { peer_id: 1 });
124	    let b_id = mgr.add(PingPongZC { peer_id: 0 });
125	    assert_eq!((a_id, b_id), (0, 1));
126	
127	    let initial = vec![(
128	        a_id,
129	        pool.get_msg(cli.size as usize).expect("seed get_msg"), // OK: fresh pool with capacity 4 satisfies a single get
130	    )];
131	
132	    let pin_cores: Vec<usize> = match cli.pin.as_deref() {
133	        None => vec![],
134	        Some(spec) => match pin::parse_cores(spec) {
135	            Ok(cores) => cores,
136	            Err(e) => {
137	                eprintln!("error: --pin: {e}");
138	                std::process::exit(2);
139	            }
140	        },
141	    };
142	
143	    let n_actors = 2;
144	    let handle = rt.startup(&mut mgr, initial, &pin_cores);
145	    handle.run(Duration::from_secs_f64(cli.warmup));
146	    handle.reset_count();
147	    handle.run(Duration::from_secs_f64(cli.duration_s));
148	    let total_count = handle.stop();
149	
150	    let mmps = total_count as f64 / cli.duration_s / 1e6;
151	    println!(
152	        "goalzc: {} messages in {:.3}s ({mmps:.3} M msg/s, {n_actors} actors, size={size} B)",
153	        fmt_commas(total_count),
154	        cli.duration_s,
155	        size = cli.size,
156	    );
157	    if pin_cores.is_empty() {
158	        println!("  pinning: none (unpinned)");
159	    } else {
160	        let plan: Vec<String> = (0..n_actors)
161	            .map(|i| format!("actor{i}→core{}", pin_cores[i % pin_cores.len()]))
162	            .collect();
163	        println!("  pinning: {}", plan.join(", "));
164	    }
165	}

